#include <spawn.h>
#include <sys/wait.h>
#include <unistd.h>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

extern char** environ;  // this process's environment, which the C library defines

// Runs a program with its standard output and error sent into a pipe, and returns what it wrote.
std::string capture(std::vector<std::string> args, int& status) {
    std::vector<char*> argv;
    for (std::string& arg : args) {
        argv.push_back(arg.data());
    }
    argv.push_back(nullptr);  // exec's argument list ends with a null pointer
    int fds[2];
    if (pipe(fds) != 0) {
        return "";
    }
    posix_spawn_file_actions_t actions;  // steps the child takes just before the exec
    posix_spawn_file_actions_init(&actions);
    posix_spawn_file_actions_adddup2(&actions, fds[1], 1);  // its fd 1 is the pipe
    posix_spawn_file_actions_adddup2(&actions, fds[1], 2);  // and fd 2, like 2>&1
    posix_spawn_file_actions_addclose(&actions, fds[0]);
    pid_t pid = 0;
    const int err = posix_spawnp(&pid, argv[0], &actions, nullptr, argv.data(), environ);
    posix_spawn_file_actions_destroy(&actions);
    close(fds[1]);  // the parent's write end: until it's closed, read never returns 0
    std::string out;
    char buf[256];
    ssize_t n = 0;
    while (err == 0 && (n = read(fds[0], buf, sizeof buf)) > 0) {
        out.append(buf, n);
    }
    close(fds[0]);
    if (err == 0) {
        waitpid(pid, &status, 0);
    }
    return out;
}

int main() {
    {
        std::ofstream fills("fills.txt");  // price and quantity, as the day's fills came in
        fills << "19280 300\n19275 100\n19290 50\n19270 200\n";
    }
    int status = 0;
    std::cout << capture({"sort", "-n", "fills.txt"}, status);
    std::cout << "sort exited with status " << WEXITSTATUS(status) << '\n';
    std::cout << capture({"sort", "-n", "fills-old.txt"}, status);
    std::cout << "sort exited with status " << WEXITSTATUS(status) << '\n';
    return 0;
}

