#include <map>
#include <string>

struct Position {
    char symbol[8];  // plain characters, no std::string
    int64_t qty;     // negative when short
};
struct Book { int64_t count; Position positions[16]; };  // what the keeper publishes

// The position keeper: reads the fills, then publishes the net positions under `name`.
void keepPositions(const std::string& name) {
    std::map<std::string, int64_t> net;
    std::string side, symbol;
    int64_t qty = 0;
    while (std::cin >> side >> symbol >> qty) {
        net[symbol] += side == "B" ? qty : -qty;
    }
    const int fd = shm_open(name.c_str(), O_RDWR, 0);  // opened by name, as a separate program would
    void* mem = mmap(nullptr, sizeof(Book), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    close(fd);
    if (mem == MAP_FAILED) {  // fails too when the open did
        _exit(1);
    }
    Book* book = static_cast<Book*>(mem);  // zero-filled, so every symbol ends in '\0'
    for (auto it = net.begin(); it != net.end() && book->count < 16; ++it) {
        Position& p = book->positions[book->count++];
        std::memcpy(p.symbol, it->first.c_str(), it->first.size() < 8 ? it->first.size() : 7);
        p.qty = it->second;
    }
    _exit(0);  // the keeper is gone, and the book stays under its name
}

int main() {
    std::string name;  // made here, under a name nothing else is using, for the keeper to fill
    int fd = -1;
    for (int i = 0; fd < 0 && i < 1000; ++i) {
        name = "/positions-" + std::to_string(getpid()) + "-" + std::to_string(i);
        fd = shm_open(name.c_str(), O_CREAT | O_EXCL | O_RDWR, 0600);
    }
    if (fd < 0) {
        return 1;  // no free name, so nothing was created
    }
    if (ftruncate(fd, sizeof(Book)) != 0) {
        shm_unlink(name.c_str());  // every way out after the create removes the name
        return 1;
    }
    close(fd);
    std::cout << std::flush;
    const pid_t pid = fork();
    if (pid == 0) {
        keepPositions(name);
    }
    int status = 0;
    waitpid(pid, &status, 0);
    std::cout << "keeper exited with status " << WEXITSTATUS(status) << '\n';
    // TODO: open the book by name, read-only, and map it with PROT_READ and MAP_SHARED.
    //       Print each position as "<symbol> <qty>", then "symbols: <count>", and unmap it.
    //       If the open or the map fails, print "no book" instead.
    shm_unlink(name.c_str());
    return 0;
}

