#include <sys/mman.h>
#include <sys/wait.h>
#include <unistd.h>
#include <atomic>
#include <cstdint>
#include <iostream>
#include <new>

struct Tick {
    int64_t seq;
    int64_t price;  // in ticks
};

constexpr uint64_t kSlots = 1024;  // a power of two, so % kSlots is cheap

// A ring for one writer process and one reader process.
struct TickRing {
    std::atomic<uint64_t> head{0};  // ticks taken so far: only the reader stores it
    std::atomic<uint64_t> tail{0};  // ticks written so far: only the writer stores it
    Tick slots[kSlots];

    bool push(const Tick& t) {  // the feed process only
        const uint64_t written = tail.load();
        if (written - head.load() == kSlots) {
            return false;  // full
        }
        slots[written % kSlots] = t;
        tail.store(written + 1);  // publishes the slot written above
        return true;
    }
    bool pop(Tick& out) {  // the strategy process only
        const uint64_t taken = head.load();
        if (taken == tail.load()) {
            return false;  // empty
        }
        out = slots[taken % kSlots];
        head.store(taken + 1);  // hands the slot back to the writer
        return true;
    }
};

int main() {
    static_assert(std::atomic<uint64_t>::is_always_lock_free, "a lock can't be shared safely");
    void* mem = mmap(nullptr, sizeof(TickRing), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        return 1;
    }
    TickRing* ring = new (mem) TickRing;  // builds the ring inside the shared pages
    const int64_t n = 100000;
    std::cout << std::flush;
    const pid_t feed = fork();
    if (feed == 0) {  // the feed process: numbers every tick, as an exchange does
        int64_t price = 19275;
        for (int64_t seq = 1; seq <= n; ++seq) {
            price += seq % 4 == 0 ? -3 : 1;
            while (!ring->push(Tick{seq, price})) {}  // full: spin until the strategy takes one
        }
        _exit(0);
    }
    int64_t received = 0, gaps = 0, upticks = 0, last = 0;  // the strategy process
    Tick t{};
    while (received < n) {
        if (ring->pop(t)) {
            ++received;
            gaps += t.seq != received;
            upticks += last != 0 && t.price > last;
            last = t.price;
        }
    }
    int status = 0;
    waitpid(feed, &status, 0);
    std::cout << "received " << received << ", gaps " << gaps << ", upticks " << upticks << '\n';
    std::cout << "last price " << last << ", feed exited with status " << WEXITSTATUS(status) << '\n';
    munmap(mem, sizeof(TickRing));
    return 0;
}

