constexpr uint64_t kSlots = 4;  // small, so the ring fills and wraps around

// A ring for one writer process and one reader process.
struct TradeRing {
    std::atomic<uint64_t> head{0};  // trades taken so far: only the reader stores it
    std::atomic<uint64_t> tail{0};  // trades written so far: only the writer stores it
    Trade slots[kSlots];
    bool push(const Trade& t) {
        const uint64_t written = tail.load();
        if (written - head.load() == kSlots) {
            return false;
        }
        slots[written % kSlots] = t;
        tail.store(written + 1);
        return true;
    }
    bool pop(Trade& out) {
        const uint64_t taken = head.load();
        if (taken == tail.load()) {
            return false;
        }
        out = slots[taken % kSlots];
        head.store(taken + 1);
        return true;
    }
};

int main() {
    std::vector<Trade> trades;  // the feed's trades, read before any fork
    Trade in{};
    while (std::cin >> in.price >> in.qty) {
        trades.push_back(in);
    }
    std::size_t received = 0;
    int64_t volume = 0, notional = 0;
    int status = 0;
    void* mem = mmap(nullptr, sizeof(TradeRing), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        return 1;
    }
    TradeRing* ring = new (mem) TradeRing;
    std::cout << std::flush;
    const pid_t feed = fork();
    if (feed == 0) {
        for (const Trade& t : trades) {
            while (!ring->push(t)) {}
        }
        _exit(0);
    }
    Trade t{};
    while (received < trades.size()) {
        if (ring->pop(t)) {
            ++received;
            volume += t.qty;
            notional += t.price * t.qty;
        }
    }
    waitpid(feed, &status, 0);
    std::cout << "feed exited with status " << WEXITSTATUS(status) << '\n';
    const double vwap = volume > 0 ? static_cast<double>(notional) / volume : 0.0;
